
<section class="page-heading"><div><p class="eyebrow">Nội dung</p><h1>Bài viết</h1><p>Quản lý Hoạt động, Thông báo và Blog hiển thị trên website.</p></div><div class="post-create-actions" aria-label="Tạo bài viết"><a class="button primary" href="post-edit.php?kind=activity">Tạo Hoạt động</a><a class="button secondary" href="post-edit.php?kind=notification">Tạo Thông báo</a><a class="button ghost" href="post-edit.php?kind=blog">Tạo Blog</a></div></section>
<div class="team-tabs"><a class="<?= $filterKind === null ? 'active' : '' ?>" href="posts.php">Tất cả</a><?php foreach (['activity','notification','blog'] as $option): ?><a class="<?= $filterKind === $option ? 'active' : '' ?>" href="posts.php?kind=<?= $option ?>"><?= ui_e(app_kind_label($option)) ?></a><?php endforeach; ?></div>
<section data-collection data-page-size="10" aria-label="Quản lý bài viết">
    <div class="collection-toolbar"><label class="search-field"><span class="sr-only">Tìm bài viết</span><?= ui_icon('magnifying-glass') ?><input type="search" data-search-input placeholder="Tìm tiêu đề, tác giả..." autocomplete="off"></label><label class="select-field"><span class="sr-only">Trạng thái bài</span><select data-category-filter><option value="">Tất cả trạng thái</option><option value="published">Đã đăng</option><option value="draft">Bản nháp / đã ẩn</option></select></label><label class="select-field"><span class="sr-only">Sắp xếp</span><select data-sort-input><option value="newest">Mới nhất</option><option value="oldest">Cũ nhất</option><option value="az">Tiêu đề A-Z</option></select></label></div>
    <div class="collection-summary"><span data-result-count aria-live="polite"><?= count($posts) ?> bài viết</span><button class="text-link" type="button" data-reset-filters hidden>Xóa bộ lọc <?= ui_icon('x') ?></button></div>
    <div class="panel table-wrap"><table><thead><tr><th>Tiêu đề</th><th>Ngày</th><th>Trạng thái</th><th>Thao tác</th></tr></thead><tbody>
        <?php if (!$posts): ?><tr><td colspan="4" class="empty table-empty"><?= ui_icon('newspaper') ?><p>Chưa có bài viết. Chọn một trong ba loại bài ở phía trên để bắt đầu.</p></td></tr><?php endif; ?>
        <?php foreach ($posts as $post): $published = ($post['status'] ?? 'draft') === 'published'; ?>
        <tr data-filter-item data-search="<?= admin_e(($post['title'] ?? '') . ' ' . ($post['author'] ?? '')) ?>" data-category="<?= $published ? 'published' : 'draft' ?>" data-date="<?= ui_timestamp($post['date'] ?? '') ?>">
            <td><strong><?= admin_e($post['title']) ?></strong><small><?= admin_e(app_kind_label($post['kind'])) ?> · <?= admin_e(strip_tags($post['excerpt'] ?? '')) ?></small></td><td><?= ui_e(ui_date($post['date'] ?? '')) ?></td><td><span class="status <?= $published ? 'published' : 'draft' ?>"><?= $published ? 'Đã đăng' : 'Bản nháp / đã ẩn' ?></span></td>
            <td class="actions"><a href="post-edit.php?id=<?= rawurlencode((string) $post['id']) ?>"><?= ui_icon('pencil-simple') ?> Sửa</a><form method="post" action="post-status.php"><input type="hidden" name="version" value="<?= (int) $post['version'] ?>"><input type="hidden" name="id" value="<?= admin_e($post['id']) ?>"><input type="hidden" name="token" value="<?= admin_e($_SESSION['post_status_token']) ?>"><button type="submit"><?= ui_icon($published ? 'eye-slash' : 'eye') ?> <?= $published ? 'Ẩn' : 'Hiện' ?></button></form><form method="post" action="post-delete.php" data-confirm="<?= admin_e('Xóa bài viết “' . $post['title'] . '”? Bài sẽ được gỡ khỏi danh sách.') ?>"><input type="hidden" name="version" value="<?= (int) $post['version'] ?>"><input type="hidden" name="id" value="<?= admin_e($post['id']) ?>"><input type="hidden" name="token" value="<?= admin_e(admin_form_token()) ?>"><button class="link-danger" type="submit"><?= ui_icon('trash') ?> Xóa</button></form></td>
        </tr>
        <?php endforeach; ?>
    </tbody></table></div>
    <?php if ($posts) ui_collection_end(); ?>
</section>
<?php admin_layout_end(); ?>
